	cmp.w	#255,d5
	beq.s	.p199				; the column is closed
	cmp.w	d5,d4
	ble.s	.p199				; y <= ridge buffer: hidden
	tst.w	d5
	beq.s	.z199				; the column was empty: no pixel is covered
	movea.l	ptPtr,a1			; the covered pixel is a contour point (x, y)
	move.w	d0,d6
	add.w	#15,d6
	move.w	d6,(a1)+
	move.w	d5,(a1)+
	move.l	a1,ptPtr
.z199:	cmp.w	#180,d4
	blt.s	.q199
	move.b	#-1,15(a2,d0.w)		; y >= 180: the column is closed, drawn on the top row
	move.w	#179,d4
	bra.s	.r199
.q199:	move.b	d4,15(a2,d0.w)
.r199:	add.w	d4,d4
	move.w	(a5,d4.w),d5			; row offset (179 - y) * 160
	move.w	d0,d6
	add.w	d6,d6
	add.w	d6,d6				; x * 4
	add.w	60(a4,d6.w),d5		; + the byte offset of the group of 16 pixels
	move.w	62(a4,d6.w),d6		; pixel mask
	lea	(a3,d5.w),a1
	or.w	d6,(a1,d1.w)			; the pixel into the plane of the band of the edge (d1 = 0, 2, 4: the plane word; dripped down later)
.p199:

	bra	.pop

	section	.bss,bss
fZW:	ds.w	150
kY:	ds.w	17
kH:	ds.w	17
